  "code": "import re\n\n\n_GDP_SHARE_RE = re.compile(\n    r\"\\b\\d+(?:\\.\\d+)?\\s*(?:%|percent)\\s+of\\s+(?:gross domestic product|gdp)\\b\",\n    re.IGNORECASE,\n)\n_FISCAL_YEAR_RE = re.compile(r\"\\b(?:FY|fiscal year|fiscal)\\s*(?:19|20)\\d{2}\\b\", re.IGNORECASE)\n_ACTUAL_DEFICIT_RE = re.compile(\n    r\"\\b(?:\"\n    r\"the federal budget deficit (?:was|fell to|declined to)|\"\n    r\"federal budget deficit of|\"\n    r\"the federal government posted a deficit of|\"\n    r\"in FY\\s*(?:19|20)\\d{2},\\s*the deficit(?: increased)?|\"\n    r\"in fiscal\\s*(?:19|20)\\d{2},\\s*the federal budget deficit|\"\n    r\"the deficit for all of fiscal\\s*(?:19|20)\\d{2}|\"\n    r\"the deficit for fiscal\\s*(?:19|20)\\d{2}\"\n    r\")\\b\",\n    re.IGNORECASE,\n)\n_BUDGET_ANCHOR_RE = re.compile(\n    r\"\\b(?:Federal Budget Deficit and Debt|Federal Budget and Debt|Federal budget deficit|budget deficit)\\b\",\n    re.IGNORECASE,\n)\n_FUTURE_RE = re.compile(\n    r\"\\b(?:project(?:ed|s|ion)?|expect(?:ed|s)?|forecast|would|will|estimate(?:d|s)?|assum(?:e|es|ed)|mid-session review)\\b\",\n    re.IGNORECASE,\n)\n\n\ndef rule_budget_deficit_paragraph(doc: dict) -> list[dict]:\n    try:\n        def normalize(text: str) -> str:\n            return \" \".join((text or \"\").split())\n\n        def trim_to_gdp(sentence: str) -> str:\n            match = _GDP_SHARE_RE.search(sentence)\n            if not match:\n                return sentence.strip(\" ,;:\")\n            return sentence[: match.end()].strip(\" ,;:\")\n\n        def split_sentences(text: str) -> list[str]:\n            parts = re.split(r\"(?<=[.!?])\\s+(?=[A-Z])\", text)\n            return [part.strip() for part in parts if part.strip()]\n\n        def build_span(text: str, item: dict) -> dict:\n            span = {\"text\": text}\n            for key in (\"page_no\", \"paragraph_no\"):\n                if key in item:\n                    span[key] = item[key]\n            return span\n\n        spans: list[dict] = []\n        seen: set[tuple[int | None, int | None, str]] = set()\n\n        for para in doc.get(\"paragraphs\") or []:\n            raw_text = para.get(\"text\") or \"\"\n            normalized = normalize(raw_text)\n            if not normalized:\n                continue\n            if not _GDP_SHARE_RE.search(normalized):\n                continue\n            if not _BUDGET_ANCHOR_RE.search(normalized):\n                continue\n\n            sentences = split_sentences(normalized)\n            for idx, sentence in enumerate(sentences):\n                sentence_has_gdp = bool(_GDP_SHARE_RE.search(sentence))\n                sentence_has_fiscal_year = bool(_FISCAL_YEAR_RE.search(sentence))\n                sentence_is_actual = bool(_ACTUAL_DEFICIT_RE.search(sentence))\n                if not sentence_is_actual:\n                    continue\n                if _FUTURE_RE.search(sentence) and not sentence_has_gdp:\n                    continue\n\n                snippet = \"\"\n                if sentence_has_gdp and (sentence_has_fiscal_year or idx == 0):\n                    snippet = trim_to_gdp(sentence)\n                elif idx + 1 < len(sentences):\n                    next_sentence = sentences[idx + 1]\n                    if _GDP_SHARE_RE.search(next_sentence) and not _FUTURE_RE.search(next_sentence):\n                        snippet = f\"{sentence.rstrip()} {trim_to_gdp(next_sentence)}\".strip()\n\n                if not snippet:\n                    continue\n\n                key = (para.get(\"page_no\"), para.get(\"paragraph_no\"), snippet)\n                if key in seen:\n                    continue\n                seen.add(key)\n                spans.append(build_span(snippet, para))\n\n        return spans\n    except Exception:\n        return []\n",
