{
  "rule_name": "rule_budget_deficit_line_window",
  "file": "/mnt/data/LSF/rules/officeqa/agentic_rule_full_data_gpt54_adaptive/all_docs/q06_what_was_the_federal_budget_deficit_for_the_most_recent_comp/rule_budget_deficit_line_window.py",
  "code": "import re\n\n\n_GDP_SHARE_RE = re.compile(\n    r\"\\b\\d+(?:\\.\\d+)?\\s*(?:%|percent)\\s+of\\s+(?:gross domestic product|gdp)\\b\",\n    re.IGNORECASE,\n)\n_FISCAL_YEAR_RE = re.compile(r\"\\b(?:FY|fiscal year|fiscal)\\s*(?:19|20)\\d{2}\\b\", re.IGNORECASE)\n_ACTUAL_DEFICIT_RE = re.compile(\n    r\"\\b(?:\"\n    r\"the federal budget deficit (?:was|fell to|declined to)|\"\n    r\"federal budget deficit of|\"\n    r\"the federal government posted a deficit of|\"\n    r\"in FY\\s*(?:19|20)\\d{2},\\s*the deficit(?: increased)?|\"\n    r\"in fiscal\\s*(?:19|20)\\d{2},\\s*the federal budget deficit|\"\n    r\"the deficit for all of fiscal\\s*(?:19|20)\\d{2}|\"\n    r\"the deficit for fiscal\\s*(?:19|20)\\d{2}\"\n    r\")\\b\",\n    re.IGNORECASE,\n)\n_BUDGET_ANCHOR_RE = re.compile(\n    r\"\\b(?:Federal Budget Deficit and Debt|Federal Budget and Debt|Federal budget deficit|budget deficit)\\b\",\n    re.IGNORECASE,\n)\n_FUTURE_RE = re.compile(\n    r\"\\b(?:project(?:ed|s|ion)?|expect(?:ed|s)?|forecast|would|will|estimate(?:d|s)?|assum(?:e|es|ed)|mid-session review)\\b\",\n    re.IGNORECASE,\n)\n\n\ndef rule_budget_deficit_line_window(doc: dict) -> list[dict]:\n    try:\n        def normalize(text: str) -> str:\n            return \" \".join((text or \"\").split())\n\n        def trim_to_gdp(text: str) -> str:\n            match = _GDP_SHARE_RE.search(text)\n            if not match:\n                return text.strip(\" ,;:\")\n            return text[: match.end()].strip(\" ,;:\")\n\n        lines = [line for line in (doc.get(\"lines\") or []) if isinstance(line, dict)]\n        spans: list[dict] = []\n        seen: set[tuple[int | None, int | None, str]] = set()\n\n        for idx, line in enumerate(lines):\n            if not (line.get(\"text\") or \"\").strip():\n                continue\n            window_lines: list[dict] = []\n            for nxt in lines[idx : idx + 8]:\n                if nxt.get(\"page_no\") != line.get(\"page_no\"):\n                    break\n                if not (nxt.get(\"text\") or \"\").strip():\n                    if window_lines:\n                        break\n                    continue\n                window_lines.append(nxt)\n            if len(window_lines) < 2:\n                continue\n\n            window_text = normalize(\" \".join(item.get(\"text\") or \"\" for item in window_lines))\n            if not _GDP_SHARE_RE.search(window_text):\n                continue\n            if not _BUDGET_ANCHOR_RE.search(window_text):\n                continue\n            if not _ACTUAL_DEFICIT_RE.search(window_text):\n                continue\n            if _FUTURE_RE.search(window_text) and not _FISCAL_YEAR_RE.search(window_text):\n                continue\n\n            snippet = trim_to_gdp(window_text)\n            key = (line.get(\"page_no\"), line.get(\"line_no\"), snippet)\n            if key in seen:\n                continue\n            seen.add(key)\n            spans.append(\n                {\n                    \"text\": snippet,\n                    \"page_no\": line.get(\"page_no\"),\n                    \"line_no\": line.get(\"line_no\"),\n                }\n            )\n\n        return spans\n    except Exception:\n        return []\n",
