                    low = candidate.lower()
                    ctext = compact(candidate)
                    if not any(term in low or term in ctext for term in ("fiscal", "fy", "budget", "deficit", "surplus", "receipts", "outlays")):
                        continue
                    key = (candidate,)
                    if key in seen:
                        continue
                    seen.add(key)
                    spans.append({"text": candidate})

        return spans
    except Exception:
        return []

def rule_specific_1991_gnp_share(doc: dict) -> list[dict]:
