                continue
            if not any(term in window_low or term in window_compact for term in ("fiscal", "fy", "budget", "deficit", "surplus", "receipts", "outlays")):
                continue
            key = (
                line.get("page_no"),
                line.get("line_no"),
                window,
            )
            if key in seen:
                continue
            seen.add(key)
            spans.append(
                {
                    "page_no": line.get("page_no"),
                    "line_no": line.get("line_no"),
                    "text": window,
                }
            )

        return spans
    except Exception:
